import type { PluginOptions } from 'claude-code'

/**
 * The plugin's `userConfig`, validated: a bad value is the default (both on). `piiGuard` covers only the personal-data refusal: with it off an
 * SSN or card number may leave, while a secret (and input too large to screen) is still refused whenever `guard` is on.
 */
export type ModOptions = { readonly guard: boolean; readonly piiGuard: boolean }

// BEGIN SHARED FLAG (generated by scripts/sync-mod-screen.mjs; edit plugins/ruflo-agentdb/hooks/options.ts)
export const flag = (value: unknown, fallback: boolean) =>
  value === true || value === 'true' || value === 'on' ? true : value === false || value === 'false' || value === 'off' ? false : fallback
// END SHARED FLAG

export function readOptions(options: PluginOptions | undefined): ModOptions {
  const o = options ?? {}
  return { guard: flag(o.guard, true), piiGuard: flag(o.piiGuard, true) }
}
